var i=`0749-suqaar`;var t=`world-0749`;var a=`SO`;var o=`eastern-africa`;var r=4;var s=51;var g={en:`Suqaar`,ua:`Сукар`};var l={en:`Suqaar is a Somalia classic prepared with beef sirloin, garlic, yellow onion, green bell pepper. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Сукар, страва кухні країни Сомалі зі складниками: яловичий сирлойн, часник, жовта цибуля, зелений солодкий перець. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var u=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 25 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 25 хвилин.`,t:[`marinating`],m:25,i:[[`beef-sirloin`,680,`g`],[`garlic`,4,`clove`],[`ground-cumin`,7,`g`],[`ground-coriander`,6,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,210,`g`],[`green-bell-pepper`,240,`g`],[`sunflower-oil`,50,`ml`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 11 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 11 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:11,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`tomato`,240,`g`],[`cilantro`,18,`g`]]}];var d={slug:i,id:t,country:`SO`,region:o,servings:4,minutes:51,title:g,text:l,steps:u};export{a as country,d as default,t as id,s as minutes,o as region,r as servings,i as slug,u as steps,l as text,g as title};